def match(orders):
    from collections import defaultdict

    # Book structure: {price: [(order_id, qty_remaining, arrival_time), ...]}
    buy_book = defaultdict(list)
    sell_book = defaultdict(list)

    # Track order metadata: {order_id: (side, price, qty_filled, arrival_time)}
    order_info = {}

    trades = []
    arrival_counter = 0

    for order in orders:
        arrival_counter += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in order_info:
                side, price, qty_filled, _ = order_info[order_id]
                if qty_filled < 0:  # Order exists and not fully processed
                    if side == 'buy':
                        buy_book[price] = [(oid, qty) for oid, qty in buy_book[price] if oid != order_id]
                        if not buy_book[price]:
                            del buy_book[price]
                    else:
                        sell_book[price] = [(oid, qty) for oid, qty in sell_book[price] if oid != order_id]
                        if not sell_book[price]:
                            del sell_book[price]
                    del order_info[order_id]

        elif order_type == 'limit':
            order_id, side, price, qty = order[1], order[2], order[3], order[4]

            # Match incoming order
            remaining = qty

            if side == 'buy':
                # Match against sell book - lowest price first, then earliest arrival
                matched_prices = sorted(sell_book.keys())
                for sell_price in matched_prices:
                    if sell_price > price or remaining == 0:
                        break

                    while remaining > 0 and sell_book[sell_price]:
                        sell_id, sell_qty = sell_book[sell_price][0]

                        trade_qty = min(remaining, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])

                        remaining -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty == 0:
                            sell_book[sell_price].pop(0)
                        else:
                            sell_book[sell_price][0] = (sell_id, sell_qty)

                if sell_book[sell_price] == []:
                    del sell_book[sell_price]

            else:  # side == 'sell'
                # Match against buy book - highest price first, then earliest arrival
                matched_prices = sorted(buy_book.keys(), reverse=True)
                for buy_price in matched_prices:
                    if buy_price < price or remaining == 0:
                        break

                    while remaining > 0 and buy_book[buy_price]:
                        buy_id, buy_qty = buy_book[buy_price][0]

                        trade_qty = min(remaining, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])

                        remaining -= trade_qty
                        buy_qty -= trade_qty

                        if buy_qty == 0:
                            buy_book[buy_price].pop(0)
                        else:
                            buy_book[buy_price][0] = (buy_id, buy_qty)

                if buy_book[buy_price] == []:
                    del buy_book[buy_price]

            # Add remaining to book
            if remaining > 0:
                if side == 'buy':
                    buy_book[price].append((order_id, remaining))
                else:
                    sell_book[price].append((order_id, remaining))
                order_info[order_id] = (side, price, -1, arrival_counter)

        elif order_type == 'ioc' or order_type == 'market':
            order_id, side = order[1], order[2]

            if order_type == 'ioc':
                price, qty = order[3], order[4]
            else:  # market
                price = float('inf') if side == 'buy' else 0
                qty = order[3]

            remaining = qty

            if side == 'buy':
                matched_prices = sorted(sell_book.keys())
                for sell_price in matched_prices:
                    if (order_type == 'ioc' and sell_price > price) or remaining == 0:
                        break

                    while remaining > 0 and sell_book[sell_price]:
                        sell_id, sell_qty = sell_book[sell_price][0]

                        trade_qty = min(remaining, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])

                        remaining -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty == 0:
                            sell_book[sell_price].pop(0)
                        else:
                            sell_book[sell_price][0] = (sell_id, sell_qty)

                if sell_book[sell_price] == []:
                    del sell_book[sell_price]

            else:  # side == 'sell'
                matched_prices = sorted(buy_book.keys(), reverse=True)
                for buy_price in matched_prices:
                    if (order_type == 'ioc' and buy_price < price) or remaining == 0:
                        break

                    while remaining > 0 and buy_book[buy_price]:
                        buy_id, buy_qty = buy_book[buy_price][0]

                        trade_qty = min(remaining, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])

                        remaining -= trade_qty
                        buy_qty -= trade_qty

                        if buy_qty == 0:
                            buy_book[buy_price].pop(0)
                        else:
                            buy_book[buy_price][0] = (buy_id, buy_qty)

                if buy_book[buy_price] == []:
                    del buy_book[buy_price]

    return trades

